SELECT ROUND(
  100.0 * COUNT(CASE WHEN EXISTS (
    SELECT 1
    FROM refunds AS r
    WHERE r.order_id = o.id AND r.amount_minor > 0
  ) THEN 1 END) / COUNT(*),
  2
)
FROM orders AS o
WHERE o.status = 'delivered_complete';

